A scientific calculator can perform more advanced mathematical operations, such as trigonometry, logarithms, and exponentiation. Here's an example of how you can build a scientific calculator in Python:

**Scientific Calculator Code**
```python
import math

def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        return "Error: Division by zero"
    return x / y

def power(x, y):
    return x ** y

def sqrt(x):
    if x < 0:
        return "Error: Square root of negative number"
    return math.sqrt(x)

def sin(x):
    return math.sin(x)

def cos(x):
    return math.cos(x)

def tan(x):
    return math.tan(x)

def log(x):
    if x <= 0:
        return "Error: Logarithm of non-positive number"
    return math.log(x)

def exp(x):
    return math.exp(x)

def main():
    print("Scientific Calculator")
    print("1. Basic Operations")
    print("2. Trigonometry")
    print("3. Exponentiation")
    print("4. Logarithms")
    print("5. Exit")

    while True:
        choice = input("Enter your choice (1-5): ")

        if choice == "1":
            print("Basic Operations")
            print("1. Addition")
            print("2. Subtraction")
            print("3. Multiplication")
            print("4. Division")
            op_choice = input("Enter your choice (1-4): ")
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))

            if op_choice == "1":
                print(f"{num1} + {num2} = {add(num1, num2)}")
            elif op_choice == "2":
                print(f"{num1} - {num2} = {subtract(num1, num2)}")
            elif op_choice == "3":
                print(f"{num1} * {num2} = {multiply(num1, num2)}")
            elif op_choice == "4":
                print(f"{num1} / {num2} = {divide(num1, num2)}")

        elif choice == "2":
            print("Trigonometry")
            print("1. Sine")
            print("2. Cosine")
            print("3. Tangent")
            trig_choice = input("Enter your choice (1-3): ")
            num = float(input("Enter a number: "))

            if trig_choice == "1":
                print(f"sin({num}) = {sin(num)}")
            elif trig_choice == "2":
                print(f"cos({num}) = {cos(num)}")
            elif trig_choice == "3":
                print(f"tan({num}) = {tan(num)}")

        elif choice == "3":
            print("Exponentiation")
            print("1. Power")
            print("2. Square Root")
            exp_choice = input("Enter your choice (1-2): ")
            num = float(input("Enter a number: "))
            if exp_choice == "1":
                num2 = float(input("Enter the power: "))
                print(f"{num} ^ {num2} = {power(num, num2)}")
            elif exp_choice == "2":
                print(f"sqrt({num}) = {sqrt(num)}")

        elif choice == "4":
            print("Logarithms")
            print("1. Natural Logarithm")
            print("2. Exponential")
            log_choice = input("Enter your choice (1-2): ")
            num = float(input("Enter a number: "))

            if log_choice == "1":
                print(f"ln({num}) = {log(num)}")
            elif log_choice == "2":
                print(f"e ^ {num} = {exp(num)}")

        elif choice == "5":
            print("Exiting the calculator")
            break

        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```
This code provides a basic scientific calculator with the following operations:

* Basic arithmetic operations (addition, subtraction, multiplication, division)
* Trigonometric functions (sine, cosine, tangent)
* Exponentiation (power, square root)
* Logarithmic functions (natural logarithm, exponential)

Note that this is a simple implementation and you may want to add more features, such as handling complex numbers, or adding more advanced mathematical functions.

You can run the code by saving it to a file (e.g., `scientific_calculator.py`) and running it from the command line using `python scientific_calculator.py`.
